final class ArchiveBadgeModel {
    let source: any NotesLoading
    private(set) var count = 0
    private(set) var text = "В архиве: 0"
    init(source: any NotesLoading) { self.source = source }
    func reload() {
        count = source.load().filter { $0.archived }.count
        text = "В архиве: \(count)"
    }
}
let notes = [
    Note(id: 41, title: "План", archived: false),
    Note(id: 42, title: "Список", archived: true)
]
let source = MemoryNotes(notes)
let model = ArchiveBadgeModel(source: source)
model.reload()
assert(model.count == 1 && model.text == "В архиве: 1")
source.notes = []
model.reload()
assert(model.count == 0 && model.text == "В архиве: 0")

Состояние нового элемента — счётчик архива, не повтор списка названий. Пустота сбрасывает прежнее значение.
